#include "hobp_bus_private.h"
#include <string.h>

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Boolean hobp_bus_init_nvfs_error (void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean hobp_bus_init_nvfs (void)
{
    return (hobp_bus_init_nvfs_error()) ;
}

//--------------------------------------------------------------------------//

static Boolean hobp_bus_init_nvfs_error (void)
{  
  if ((nvfs_size_is_valid(nvfs_hobp_bus_error, sizeof(Hobp_Bus_Error)) == NVFS_OK) && (nvfs_rd (nvfs_hobp_bus_error , &hobp_bus_vars.err)== NVFS_OK))
    {
      return (TRUE) ;
    }

  nvfs_delete(nvfs_hobp_bus_error) ;
  
  memset(&hobp_bus_vars.err, NULL , sizeof(Hobp_Bus_Error)) ;
  
  switch (nvfs_wr_create (nvfs_hobp_bus_error, &hobp_bus_vars.err , sizeof(Hobp_Bus_Error)))
    {
      case NVFS_OK : return hobp_bus_init_nvfs_error() ;  
    }      

  return FALSE ;  
}


